IF OBJECT_ID('dbo.DOI_I18N', 'U') IS NULL
BEGIN
    CREATE TABLE dbo.DOI_I18N (
        LANG_KEY NVARCHAR(500) NOT NULL,
        KO_TEXT  NVARCHAR(MAX) NULL,
        VI_TEXT  NVARCHAR(MAX) NULL,
        USE_YN   VARCHAR(1) DEFAULT 'Y',
        INIT_DT  DATETIME DEFAULT GETDATE()
